import net from "node:net";import tls from "node:tls";import fs from "node:fs";
const dir=process.argv[2],cert=fs.readFileSync(dir+"/cert.pem"),key=fs.readFileSync(dir+"/key.pem");
const server=tls.createServer({cert,key},s=>s.on("data",b=>s.end(b)));await new Promise(r=>server.listen(0,"127.0.0.1",r));const port=server.address().port;
const calls=[],original=net.Socket.prototype.connect;
net.Socket.prototype.connect=function(...args){const p=args[0];calls.push({types:args.map(v=>typeof v),array:Array.isArray(p),host:p?.host??args[1],port:p?.port??(typeof p==="number"?p:null),keys:p&&typeof p==="object"?Object.keys(p):[],socket:p?.socket?{address:p.socket.remoteAddress,port:p.socket.remotePort}:null,self:{address:this.remoteAddress,port:this.remotePort}});return original.apply(this,args)};
try{const raw=net.connect(port,"127.0.0.1");await new Promise((r,j)=>{raw.once("connect",r);raw.once("error",j)});const client=tls.connect({socket:raw,servername:"localhost",ca:cert});const result=await new Promise((r,j)=>{client.once("secureConnect",()=>client.write("owned-probe"));client.once("data",v=>r(v.toString()));client.once("error",j)});console.log(JSON.stringify({calls,result,port,postgresStarts:0,sourceAccesses:0}));client.destroy()}finally{net.Socket.prototype.connect=original;server.close()}
